using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using RogControl;

public static class DiscoveryGuiTests {
 static int checks;static readonly BindingFlags Private=BindingFlags.NonPublic|BindingFlags.Instance;
 static void Check(bool good,string label){checks++;if(!good)throw new Exception(label);}
 static object InvokeStatic(string method,params object[] values){return typeof(MainWindow).GetMethod(method,BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,values);}
 static bool Known(string pid,string name,bool board=false){return (bool)InvokeStatic("DiscoverySignatureKnown",pid,name,board);}
 static Dictionary<string,object> Hardware(char id,string pid,string name){return new Dictionary<string,object>{{"deviceId",new string(id,64)},{"vid","0B05"},{"pid",pid},{"name",name},{"nameSource","busReportedDeviceDesc"},{"present",true},{"vendorConfirmed",true},{"controlSupported",false},{"physicalIdentityConfirmed",true},{"identityScope","usbParent"},{"transport","USB"},{"functionCount",4},{"observedProductIds",new[]{pid}}};}
 static IEnumerable<T> Logical<T>(DependencyObject value) where T:DependencyObject {if(value is T)yield return (T)value;foreach(var child in LogicalTreeHelper.GetChildren(value).OfType<DependencyObject>())foreach(var match in Logical<T>(child))yield return match;}
 static void Render(MainWindow window,int height,string file){var frame=(FrameworkElement)window.Content;frame.Measure(new Size(1538,height));frame.Arrange(new Rect(0,0,1538,height));frame.UpdateLayout();var bitmap=new RenderTargetBitmap(1538,height,96,96,PixelFormats.Pbgra32);bitmap.Render(frame);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using(var stream=File.Create(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,file)))png.Save(stream);}
 [STAThread] public static void Main(){var app=new Application();Check(Known("1D41","ROG DELTA II-KJP (2.4GHz)"),"current headset signature");Check(!Known("1D41","Different future headset"),"same PID future variant not hidden");Check(!Known("1DA2","ROG AZOTH EXTREME"),"base keyboard does not imply anniversary edition");Check(Known("1DA2","ROG AZOTH EXTREME EDITION 20"),"exact anniversary keyboard signature");Check(!Known("1AA6","AURA LED Controller"),"generic Aura does not prove motherboard model");Check(Known("1AA6","AURA LED Controller",true),"Aura on actual known motherboard");Check(!Known("1C83","Motherboard LCD Panel"),"generic LCD requires known actual board");Check(!Known("1AD0","ROG Future Receiver"),"existing receiver PID not enough for new name");Check(!Known("1C76","ROG RYUO IV Standard"),"unimplemented cooler stays identification only");
  foreach(var source in new[]{new[]{"busReportedDeviceDesc","设备提供的名称"},new[]{"friendlyName","Windows 显示名称"},new[]{"deviceDescription","Windows 设备描述"}})Check((string)InvokeStatic("DiscoveryNameSource",new Dictionary<string,object>{{"nameSource",source[0]}})==source[1],"friendly name-source label");
  var valid=Hardware('a',"1D41","ROG DELTA II-KJP (2.4GHz)");Check((bool)InvokeStatic("DiscoveryEntryValid",valid),"read-only valid identity");valid["controlSupported"]=true;Check(!(bool)InvokeStatic("DiscoveryEntryValid",valid),"discovery cannot authorize setters");valid["controlSupported"]=false;valid["vendorConfirmed"]=false;Check(!(bool)InvokeStatic("DiscoveryEntryValid",valid),"unverified vendor rejected");valid["vendorConfirmed"]=true;valid["deviceId"]="not-stable-id";Check(!(bool)InvokeStatic("DiscoveryEntryValid",valid),"invalid identity rejected");valid["deviceId"]=new string('a',64);valid["present"]=false;Check(!(bool)InvokeStatic("DiscoveryEntryValid",valid),"absent snapshot not listed");
  var window=new MainWindow(true);((MachineInfo)typeof(MainWindow).GetField("info",Private).GetValue(window)).Board="ROG CROSSHAIR X870E EXTREME";var identities=(List<Dictionary<string,object>>)typeof(MainWindow).GetField("discoveredHardware",Private).GetValue(window);identities.Add(Hardware('a',"1D41","ROG DELTA II-KJP (2.4GHz)"));identities.Add(Hardware('b',"1D41","ROG DELTA II-KJP (2.4GHz)"));identities.Add(Hardware('c',"1D41","合成示例 · 同 PID 的未来型号"));identities.Add(Hardware('d',"1C76","ROG RYUO IV Standard · 合成数据"));typeof(MainWindow).GetField("discoveryCompleted",Private).SetValue(window,true);typeof(MainWindow).GetField("discoveryMessage",Private).SetValue(window,"合成验证 · 4 个独立身份 · 未执行设备扫描");typeof(MainWindow).GetField("discoveryCapturedAt",Private).SetValue(window,"合成时间");typeof(MainWindow).GetField("page",Private).SetValue(window,"设备");typeof(MainWindow).GetMethod("UpdateOriginalNavigation",Private).Invoke(window,null);var content=(StackPanel)typeof(MainWindow).GetField("content",Private).GetValue(window);content.Children.Clear();typeof(MainWindow).GetMethod("OriginalDeviceGallery",Private).Invoke(window,null);Check(!Logical<Expander>(content).Any(),"original device grid has no scanner dump");Check(!Logical<Button>(content).Any(b=>Convert.ToString(b.Content)=="查看设备信息"),"identity details are reached from compatibility tools");content.Children.Clear();typeof(MainWindow).GetField("page",Private).SetValue(window,"设备兼容");typeof(MainWindow).GetMethod("OriginalDiscoveryGallery",Private).Invoke(window,new object[]{content});var expanders=Logical<Expander>(content).ToList();Check(expanders.Count==1&&!expanders[0].IsExpanded,"all hardware starts folded");Check(Convert.ToString(expanders[0].Header).Contains("4")&&((StackPanel)expanders[0].Content).Children.Count==4,"same-model multiple physical identities retained");Check(Logical<Button>(content).Count(b=>Convert.ToString(b.Content)=="查看设备信息")==2,"new variant and unknown PID receive metadata entrance");Render(window,1200,"discovery-gallery.png");
  content.Children.Clear();typeof(MainWindow).GetMethod("OriginalDiscoveredDevicePage",Private).Invoke(window,new object[]{new string('a',64)});Check(Logical<TextBlock>(content).Any(t=>t.Text=="仅身份信息 · 此页不提供控制"),"known identity details do not claim control");Check(!Logical<Button>(content).Any(b=>Convert.ToString(b.Content).Contains("应用")),"known identity page has no apply controls");
  content.Children.Clear();typeof(MainWindow).GetMethod("OriginalDiscoveredDevicePage",Private).Invoke(window,new object[]{new string('c',64)});Check(Logical<TextBlock>(content).Any(t=>t.Text=="仅识别 · 尚未适配控制"),"future same-PID variant explicitly unsupported");Check(!Logical<Button>(content).Any(b=>Convert.ToString(b.Content).Contains("应用")),"unknown identity page has no apply controls");Check(Logical<TextBlock>(content).Any(t=>t.Text=="设备提供的名称"),"detail source label nontechnical");Render(window,826,"discovery-identity.png");identities.Clear();content.Children.Clear();typeof(MainWindow).GetMethod("OriginalDiscoveredDevicePage",Private).Invoke(window,new object[]{new string('c',64)});Check(Logical<TextBlock>(content).Any(t=>t.Text.Contains("未在当前扫描结果")),"removed identity cannot retain present claim");
  Console.WriteLine("Discovery GUI: "+checks+" pure checks passed. Unshown render-only window; no scan, worker request, device command or hook.");app.Shutdown();
 }
}
